"use client";
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useParams, useRouter } from 'next/navigation';
import Sidebar from "../../../components/sidebar"; // Importation de Sidebar
import Navbar from "../../../components/Navbar";

export default function Edituser() {
  const [inputs, setInputs] = useState({
    nom: "",
    prenom: "",
    email: "",
    motDePasse: "",
    annee: "",
    classe: "",
    filiere: "",
  });
  const { id } = useParams();

  useEffect(() => {
    getUser();
  }, []);

  function getUser() {
    axios.get(`http://localhost:5000/api/getetudiant/${id}`).then(function(response) {
      const userData = response.data[0]; // Récupérer la première ligne de données (un utilisateur)
      setInputs({
        nom: userData.nom,
        prenom: userData.prenom,
        email: userData.email,
        motDePasse: userData.motDePasse,
        annee: userData.annee,
        classe: userData.classe,
        filiere: userData.filiere,
      });
    }).catch(err => {
      console.error("Erreur lors de la récupération de l'étudiant:", err);
    });
  }

  const handleChange = (event) => {
    const { name, value } = event.target;
    setInputs(prevValues => ({ ...prevValues, [name]: value }));
  }

  const router = useRouter();

  const handleSubmit = (event) => {
    event.preventDefault();

    axios.put(`http://localhost:5000/api/editetudiant/${id}`, inputs)
      .then(function(response) {
        router.push('/users/readEtu'); // Redirige vers la page d'accueil après la mise à jour
      })
      .catch(err => {
        console.error("Erreur lors de la mise à jour de l'étudiant:", err);
      });
  }

  return (
    <div className="flex h-screen w-screen">
      {/* Sidebar */}
      <Sidebar className="h-screen" />
      <div className="w-full flex flex-col h-screen">
        {/* Navbar */}
        <Navbar />
        <div className="w-full flex-1 py-5 flex flex-col items-center overflow-hidden">
    <div className="max-w-md mx-auto mt-5">
    <button 
              onClick={() => router.push("/users/readEtu")}
              className="mb-5 flex items-center text-blue-600 hover:text-blue-800 transition"
            >
              ← Retour à la gestion des Etudiants
            </button>
      <h1 className="text-2xl text-center mb-2">Modifier l'Étudiant</h1>
      <form onSubmit={handleSubmit}>
        <div className="mb-5">
          <label htmlFor="nom" className="block text-sm font-medium text-gray-900">Nom</label>
          <input
            type="text"
            name="nom"
            id="nom"
            value={inputs.nom || ''}
            className="w-full px-4 py-2 mt-2 border border-blue-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none shadow-sm transition"
            placeholder="Nom..."
            onChange={handleChange}
          />
        </div>
        <div className="mb-5">
          <label htmlFor="prenom" className="block text-sm font-medium text-gray-900">Prénom</label>
          <input
            type="text"
            name="prenom"
            id="prenom"
            value={inputs.prenom || ''}
            className="w-full px-4 py-2 mt-2 border border-blue-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none shadow-sm transition"
            placeholder="Prénom..."
            onChange={handleChange}
          />
        </div>
        <div className="mb-5">
          <label htmlFor="email" className="block text-sm font-medium text-gray-900">Email</label>
          <input
            type="email"
            name="email"
            id="email"
            value={inputs.email || ''}
            className="w-full px-4 py-2 mt-2 border border-blue-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none shadow-sm transition"
            placeholder="Email..."
            onChange={handleChange}
          />
        </div>
        <div className="mb-5">
          <label htmlFor="motDePasse" className="block text-sm font-medium text-gray-900">Mot de passe</label>
          <input
            type="password"
            name="motDePasse"
            id="motDePasse"
            value={inputs.motDePasse || ''}
            className="w-full px-4 py-2 mt-2 border border-blue-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none shadow-sm transition"
            placeholder="Mot de passe..."
            onChange={handleChange}
          />
        </div>
        <div className="mb-5">
          <label htmlFor="annee" className="block text-sm font-medium text-gray-900">Année</label>
          <input
            type="number"
            name="annee"
            id="annee"
            value={inputs.annee || ''}
            className="w-full px-4 py-2 mt-2 border border-blue-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none shadow-sm transition"
            placeholder="Année..."
            onChange={handleChange}
          />
        </div>
        <div className="mb-5">
          <label htmlFor="classe" className="block text-sm font-medium text-gray-900">Classe</label>
          <input
            type="text"
            name="classe"
            id="classe"
            value={inputs.classe || ''}
            className="w-full px-4 py-2 mt-2 border border-blue-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none shadow-sm transition"
            placeholder="Classe..."
            onChange={handleChange}
          />
        </div>
        <div className="mb-5">
          <label htmlFor="filiere" className="block text-sm font-medium text-gray-900">Filière</label>
          <input
            type="text"
            name="filiere"
            id="filiere"
            value={inputs.filiere || ''}
            className="w-full px-4 py-2 mt-2 border border-blue-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none shadow-sm transition"
            placeholder="Filière..."
            onChange={handleChange}
          />
        </div>
        <button
                type="submit"
                className="bg-blue-500 text-white w-full py-2 px-5 rounded-lg shadow-md hover:bg-blue-600"
              >
                Modifier
              </button>
      </form>
      
      </div>

    </div>
  </div>
</div>
  );
}
